An enterprise-grade, high-performance, modular CDN Edge Cache implemented in C#. This implementation features a fully concurrent, zero-dependency architecture that runs natively on .NET 8.0+.

### Architecture Diagram

```
   [ Client Request ]
           │
           ▼
┌──────────────────────────────────────┐
│       Edge Proxy Ingester            │◀── [Admin Purge Endpoint]
├──────────────────────────────────────┤
│  • Request Normalizer                │
│  • Media Pattern Matcher             │
│  • Origin Shielding / Coalescing     │
└──────────────────────────────────────┘
           │
           ├─── L1 Hit (RAM - LRU Cache) ─────────► [ Return Cache ]
           │
           ├─── L1 Miss / L2 Hit (NVMe SSD)
           │     • Read from Disk Async
           │     • Promote L2 -> L1 (Evicts LRU L1)
           │     └──► [ Return Cache ]
           │
           └─── L1/L2 Cache Miss (Origin Shield)
                 • Coalesce duplicate requests (Request Collapsing)
                 • Fetch from Origin (Mock Network Stream)
                 • Write to Cache Tiers (Write-Through/Write-Back)
                 └──► [ Return Cache ]
```

---

### Implementation

```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Channels;
using System.Threading.Tasks;

namespace EnterpriseCdn.Edge
{
    #region Models & Interfaces

    public record CacheItem(
        string Key, 
        byte[] Data, 
        string ContentType, 
        string[] Tags, 
        DateTime ExpiresAt
    );

    public enum MediaType
    {
        Generic,
        HlsPlaylist,     // .m3u8
        HlsSegment,      // .ts
        DashManifest,    // .mpd
        DashSegment,     // .m4s
        ProgressiveMedia // .mp4, .webm, etc.
    }

    public enum WritePolicy
    {
        WriteThrough, // Write to L1 and L2 synchronously
        WriteBack     // Write to L1, persist to L2 asynchronously on demotion
    }

    public interface ICacheTierManager : IAsyncDisposable
    {
        Task<CacheItem?> GetAsync(string key);
        Task SetAsync(CacheItem item);
        Task EvictAsync(string key);
        Task ClearAllAsync();
        CacheMetrics GetMetrics();
    }

    public interface IPurgeController : IAsyncDisposable
    {
        Task RegisterKeyAsync(string key, string[] tags);
        Task PurgeExactAsync(string key);
        Task PurgeByTagAsync(string tag);
        Task PurgeByWildcardAsync(string wildcardPattern);
        void EnqueueWebhookBroadcast(string purgeAction, string pattern);
    }

    public record CacheMetrics(
        long L1BytesUsed, 
        long L1MaxBytes, 
        long L1ItemCount,
        long L2BytesUsed, 
        long L2MaxBytes, 
        long L2ItemCount,
        long CacheHits, 
        long CacheMisses
    );

    #endregion

    #region L1 RAM Cache (Thread-Safe LRU)

    internal class L1CacheEntry
    {
        public string Key { get; }
        public CacheItem Item { get; set; }
        public long SizeBytes { get; }

        public L1CacheEntry(string key, CacheItem item)
        {
            Key = key;
            Item = item;
            SizeBytes = item.Data.Length + (key.Length * 2) + 256; // Fast rough estimation in bytes
        }
    }

    public class L1LRUCache
    {
        private readonly long _maxBytes;
        private readonly object _lock = new();
        private readonly Dictionary<string, LinkedListNode<L1CacheEntry>> _map = new();
        private readonly LinkedList<L1CacheEntry> _list = new();
        private long _currentBytes;

        public long CurrentBytes => Interlocked.Read(ref _currentBytes);
        public long Count { get { lock (_lock) { return _map.Count; } } }

        public L1LRUCache(long maxBytes)
        {
            _maxBytes = maxBytes;
        }

        public bool TryGet(string key, out CacheItem? item)
        {
            lock (_lock)
            {
                if (_map.TryGetValue(key, out var node))
                {
                    _list.Remove(node);
                    _list.AddFirst(node); // Move to MRU position
                    item = node.Value.Item;
                    return true;
                }
            }
            item = null;
            return false;
        }

        public List<CacheItem> Put(CacheItem item, out List<CacheItem> demotedItems)
        {
            demotedItems = new List<CacheItem>();
            var newEntry = new L1CacheEntry(item.Key, item);

            lock (_lock)
            {
                if (_map.TryGetValue(item.Key, out var existingNode))
                {
                    _currentBytes -= existingNode.Value.SizeBytes;
                    _list.Remove(existingNode);
                    _map.Remove(item.Key);
                }

                while (_currentBytes + newEntry.SizeBytes > _maxBytes && _list.Count > 0)
                {
                    var lruNode = _list.Last;
                    if (lruNode != null)
                    {
                        _list.RemoveLast();
                        _map.Remove(lruNode.Value.Key);
                        _currentBytes -= lruNode.Value.SizeBytes;
                        demotedItems.Add(lruNode.Value.Item);
                    }
                }

                var newNode = new LinkedListNode<L1CacheEntry>(newEntry);
                _list.AddFirst(newNode);
                _map[item.Key] = newNode;
                _currentBytes += newEntry.SizeBytes;
            }

            return demotedItems;
        }

        public bool TryRemove(string key, out CacheItem? removedItem)
        {
            lock (_lock)
            {
                if (_map.TryGetValue(key, out var node))
                {
                    _list.Remove(node);
                    _map.Remove(key);
                    _currentBytes -= node.Value.SizeBytes;
                    removedItem = node.Value.Item;
                    return true;
                }
            }
            removedItem = null;
            return false;
        }

        public void Clear()
        {
            lock (_lock)
            {
                _list.Clear();
                _map.Clear();
                _currentBytes = 0;
            }
        }
    }

    #endregion

    #region Cache Tier Manager (L1 RAM & L2 Disk SSD)

    public class CacheTierManager : ICacheTierManager
    {
        private readonly L1LRUCache _l1Cache;
        private readonly string _l2StorageDirectory;
        private readonly long _l2MaxBytes;
        private readonly WritePolicy _writePolicy;
        private readonly ConcurrentDictionary<string, (long Size, DateTime LastAccess)> _l2Catalog = new();
        private readonly Channel<CacheItem> _writeBackChannel = Channel.CreateUnbounded<CacheItem>(new UnboundedChannelOptions { SingleReader = true });
        private readonly CancellationTokenSource _cts = new();
        private readonly Task _writeBackWorkerTask;

        private long _cacheHits;
        private long _cacheMisses;
        private long _l2BytesUsed;

        public CacheTierManager(long l1MaxBytes, string l2StorageDirectory, long l2MaxBytes, WritePolicy writePolicy)
        {
            _l1Cache = new L1LRUCache(l1MaxBytes);
            _l2StorageDirectory = l2StorageDirectory;
            _l2MaxBytes = l2MaxBytes;
            _writePolicy = writePolicy;

            if (!Directory.Exists(_l2StorageDirectory))
            {
                Directory.CreateDirectory(_l2StorageDirectory);
            }

            InitializeL2Catalog();
            _writeBackWorkerTask = Task.Run(ProcessWriteBackQueueAsync);
        }

        private void InitializeL2Catalog()
        {
            var files = Directory.GetFiles(_l2StorageDirectory, "*.cache");
            foreach (var file in files)
            {
                try
                {
                    var fileInfo = new FileInfo(file);
                    var key = ReadKeyFromL2File(file);
                    if (!string.IsNullOrEmpty(key))
                    {
                        _l2Catalog[key] = (fileInfo.Length, fileInfo.LastAccessTimeUtc);
                        Interlocked.Add(ref _l2BytesUsed, fileInfo.Length);
                    }
                }
                catch
                {
                    // Ignore malformed files on startup
                }
            }
        }

        public async Task<CacheItem?> GetAsync(string key)
        {
            // 1. Check L1 RAM
            if (_l1Cache.TryGet(key, out var l1Item))
            {
                Interlocked.Increment(ref _cacheHits);
                return l1Item;
            }

            // 2. Check L2 NVMe SSD
            if (_l2Catalog.ContainsKey(key))
            {
                var item = await ReadFromL2Async(key).ConfigureAwait(false);
                if (item != null)
                {
                    Interlocked.Increment(ref _cacheHits);

                    // Promote to L1 Async
                    var demoted = _l1Cache.Put(item, out var demotedItems);
                    foreach (var demotedItem in demotedItems)
                    {
                        HandleDemotedItem(demotedItem);
                    }

                    return item;
                }
            }

            Interlocked.Increment(ref _cacheMisses);
            return null;
        }

        public async Task SetAsync(CacheItem item)
        {
            // Save to L1 RAM
            var demotedItems = _l1Cache.Put(item, out var l1Demoted);

            // Handle Demotions if policy is Write-Back
            foreach (var demotedItem in l1Demoted)
            {
                HandleDemotedItem(demotedItem);
            }

            if (_writePolicy == WritePolicy.WriteThrough)
            {
                await WriteToL2Async(item).ConfigureAwait(false);
            }
            else
            {
                // Instant hot cache response; background NVMe serialization
                await _writeBackChannel.Writer.WriteAsync(item).ConfigureAwait(false);
            }
        }

        public async Task EvictAsync(string key)
        {
            _l1Cache.TryRemove(key, out _);
            await DeleteFromL2Async(key).ConfigureAwait(false);
        }

        public Task ClearAllAsync()
        {
            _l1Cache.Clear();
            foreach (var key in _l2Catalog.Keys)
            {
                DeleteFromL2Async(key).Wait();
            }
            return Task.CompletedTask;
        }

        public CacheMetrics GetMetrics()
        {
            return new CacheMetrics(
                L1BytesUsed: _l1Cache.CurrentBytes,
                L1MaxBytes: 10 * 1024 * 1024, // Configured boundary max
                L1ItemCount: _l1Cache.Count,
                L2BytesUsed: Interlocked.Read(ref _l2BytesUsed),
                L2MaxBytes: _l2MaxBytes,
                L2ItemCount: _l2Catalog.Count,
                CacheHits: Interlocked.Read(ref _cacheHits),
                CacheMisses: Interlocked.Read(ref _cacheMisses)
            );
        }

        private void HandleDemotedItem(CacheItem item)
        {
            if (_writePolicy == WritePolicy.WriteBack)
            {
                _writeBackChannel.Writer.TryWrite(item);
            }
        }

        private async Task ProcessWriteBackQueueAsync()
        {
            try
            {
                while (await _writeBackChannel.Reader.WaitToReadAsync(_cts.Token).ConfigureAwait(false))
                {
                    while (_writeBackChannel.Reader.TryRead(out var item))
                    {
                        await WriteToL2Async(item).ConfigureAwait(false);
                    }
                }
            }
            catch (OperationCanceledException) { }
        }

        #region Physical NVMe File I/O Serialization Engine

        private string GetL2FilePath(string key)
        {
            using var sha = SHA256.Create();
            var hash = sha.ComputeHash(Encoding.UTF8.GetBytes(key));
            var fileName = Convert.ToHexString(hash) + ".cache";
            return Path.Combine(_l2StorageDirectory, fileName);
        }

        private async Task WriteToL2Async(CacheItem item)
        {
            var filePath = GetL2FilePath(item.Key);

            // Format layout:
            // [Magic Number: 4B][Expiry Ticks: 8B][Key Length: 4B][Key: UB][ContentType Length: 4B][ContentType: UB][Tags Count: 4B][Tags array][Data Length: 4B][Data: UB]

            using var ms = new MemoryStream();
            using (var writer = new BinaryWriter(ms, Encoding.UTF8, leaveOpen: true))
            {
                writer.Write(0xC0D1C0D1); // Magic Header Identification
                writer.Write(item.ExpiresAt.Ticks);
                writer.Write(item.Key);
                writer.Write(item.ContentType);
                writer.Write(item.Tags.Length);
                foreach (var tag in item.Tags)
                {
                    writer.Write(tag);
                }
                writer.Write(item.Data.Length);
                writer.Write(item.Data);
            }

            var binaryBuffer = ms.ToArray();
            var fileSize = binaryBuffer.Length;

            await EnforceL2EvictionBoundariesAsync(fileSize).ConfigureAwait(false);

            try
            {
                await File.WriteAllBytesAsync(filePath, binaryBuffer, _cts.Token).ConfigureAwait(false);

                if (!_l2Catalog.ContainsKey(item.Key))
                {
                    Interlocked.Add(ref _l2BytesUsed, fileSize);
                }
                else
                {
                    var oldSize = _l2Catalog[item.Key].Size;
                    Interlocked.Add(ref _l2BytesUsed, fileSize - oldSize);
                }

                _l2Catalog[item.Key] = (fileSize, DateTime.UtcNow);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"[L2 Write-Error] Failed to persist key {item.Key} to disk: {ex.Message}");
            }
        }

        private async Task<CacheItem?> ReadFromL2Async(string key)
        {
            var filePath = GetL2FilePath(key);
            if (!File.Exists(filePath)) return null;

            try
            {
                var bytes = await File.ReadAllBytesAsync(filePath, _cts.Token).ConfigureAwait(false);
                using var ms = new MemoryStream(bytes);
                using var reader = new BinaryReader(ms, Encoding.UTF8);

                if (reader.ReadInt32() != 0xC0D1C0D1) return null; // Bad file validation

                var ticks = reader.ReadInt64();
                var expiresAt = new DateTime(ticks, DateTimeKind.Utc);
                if (expiresAt < DateTime.UtcNow)
                {
                    await DeleteFromL2Async(key).ConfigureAwait(false);
                    return null;
                }

                var parsedKey = reader.ReadString();
                var contentType = reader.ReadString();
                var tagCount = reader.ReadInt32();
                var tags = new string[tagCount];
                for (int i = 0; i < tagCount; i++)
                {
                    tags[i] = reader.ReadString();
                }

                var dataLength = reader.ReadInt32();
                var data = reader.ReadBytes(dataLength);

                _l2Catalog[key] = (bytes.Length, DateTime.UtcNow);
                return new CacheItem(parsedKey, data, contentType, tags, expiresAt);
            }
            catch
            {
                return null;
            }
        }

        private async Task DeleteFromL2Async(string key)
        {
            if (_l2Catalog.TryRemove(key, out var info))
            {
                Interlocked.Add(ref _l2BytesUsed, -info.Size);
                var filePath = GetL2FilePath(key);
                if (File.Exists(filePath))
                {
                    await Task.Run(() => File.Delete(filePath)).ConfigureAwait(false);
                }
            }
        }

        private string ReadKeyFromL2File(string filePath)
        {
            try
            {
                using var fs = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read);
                using var reader = new BinaryReader(fs, Encoding.UTF8);
                if (reader.ReadInt32() != 0xC0D1C0D1) return string.Empty;
                reader.ReadInt64(); // skip expiry ticks
                return reader.ReadString(); // return key
            }
            catch
            {
                return string.Empty;
            }
        }

        private async Task EnforceL2EvictionBoundariesAsync(long bytesRequired)
        {
            while (Interlocked.Read(ref _l2BytesUsed) + bytesRequired > _l2MaxBytes && !_l2Catalog.IsEmpty)
            {
                var oldestItem = _l2Catalog
                    .OrderBy(x => x.Value.LastAccess)
                    .FirstOrDefault();

                if (oldestItem.Key != null)
                {
                    Console.ForegroundColor = ConsoleColor.DarkYellow;
                    Console.WriteLine($"[L2 Eviction-Cycle] Demoting/Evicting Key '{oldestItem.Key}' to satisfy NVMe storage caps.");
                    Console.ResetColor();
                    await DeleteFromL2Async(oldestItem.Key).ConfigureAwait(false);
                }
                else
                {
                    break;
                }
            }
        }

        #endregion

        public async ValueTask DisposeAsync()
        {
            _cts.Cancel();
            try
            {
                await _writeBackWorkerTask.ConfigureAwait(false);
            }
            catch { }

            _cts.Dispose();
            GC.SuppressFinalize(this);
        }
    }

    #endregion

    #region Purge Controller (Lock-Free Invalidation & Webhook Broadcasts)

    public class PurgeController : IPurgeController
    {
        private readonly ICacheTierManager _cacheTierManager;
        private readonly ConcurrentDictionary<string, ConcurrentBag<string>> _tagToKeysIndex = new();
        private readonly ConcurrentDictionary<string, HashSet<string>> _keyToTagsIndex = new();
        private readonly Channel<PurgeNotification> _webhookChannel = Channel.CreateUnbounded<PurgeNotification>(new UnboundedChannelOptions { SingleReader = true });
        private readonly HttpClient _httpClient = new(new SocketsHttpHandler { PooledConnectionLifetime = TimeSpan.FromMinutes(5) });
        private readonly CancellationTokenSource _cts = new();
        private readonly Task _webhookBroadcasterTask;
        private readonly List<string> _webhookEndpoints = new();

        public record PurgeNotification(string Action, string Pattern, int RetryCount = 0);

        public PurgeController(ICacheTierManager cacheTierManager, IEnumerable<string> webhookEndpoints)
        {
            _cacheTierManager = cacheTierManager;
            _webhookEndpoints.AddRange(webhookEndpoints);
            _webhookBroadcasterTask = Task.Run(ProcessWebhookBroadcastsAsync);
        }

        public Task RegisterKeyAsync(string key, string[] tags)
        {
            var cleanTags = tags.Select(t => t.Trim().ToLowerInvariant()).ToArray();
            _keyToTagsIndex.AddOrUpdate(key, 
                _ => new HashSet<string>(cleanTags), 
                (_, oldTags) => { lock(oldTags) { oldTags.UnionWith(cleanTags); } return oldTags; }
            );

            foreach (var tag in cleanTags)
            {
                _tagToKeysIndex.GetOrAdd(tag, _ => new ConcurrentBag<string>()).Add(key);
            }
            return Task.CompletedTask;
        }

        public async Task PurgeExactAsync(string key)
        {
            Console.ForegroundColor = ConsoleColor.Red;
            Console.WriteLine($"[Purge-Action] Invalidating unique absolute key: {key}");
            Console.ResetColor();

            await _cacheTierManager.EvictAsync(key).ConfigureAwait(false);

            if (_keyToTagsIndex.TryRemove(key, out var tags))
            {
                // Leave dangling keys in tag map; cleaned up on evaluation
            }

            EnqueueWebhookBroadcast("PURGE_EXACT", key);
        }

        public async Task PurgeByTagAsync(string tag)
        {
            var cleanTag = tag.Trim().ToLowerInvariant();
            Console.ForegroundColor = ConsoleColor.Red;
            Console.WriteLine($"[Purge-Action] Invalidating by cache tagging identifier: {cleanTag}");
            Console.ResetColor();

            if (_tagToKeysIndex.TryRemove(cleanTag, out var associatedKeys))
            {
                var keysToPurge = associatedKeys.Distinct().ToArray();
                foreach (var key in keysToPurge)
                {
                    await _cacheTierManager.EvictAsync(key).ConfigureAwait(false);
                    _keyToTagsIndex.TryRemove(key, out _);
                }
            }

            EnqueueWebhookBroadcast("PURGE_TAG", cleanTag);
        }

        public async Task PurgeByWildcardAsync(string wildcardPattern)
        {
            Console.ForegroundColor = ConsoleColor.Red;
            Console.WriteLine($"[Purge-Action] Evaluated complex wildcard purge pattern: {wildcardPattern}");
            Console.ResetColor();

            var regexPattern = "^" + Regex.Escape(wildcardPattern).Replace("\\*", ".*") + "$";
            var regex = new Regex(regexPattern, RegexOptions.IgnoreCase | RegexOptions.Compiled);

            var activeKeys = _keyToTagsIndex.Keys.ToArray();
            foreach (var key in activeKeys)
            {
                if (regex.IsMatch(key))
                {
                    await _cacheTierManager.EvictAsync(key).ConfigureAwait(false);
                    _keyToTagsIndex.TryRemove(key, out _);
                }
            }

            EnqueueWebhookBroadcast("PURGE_WILDCARD", wildcardPattern);
        }

        public void EnqueueWebhookBroadcast(string purgeAction, string pattern)
        {
            _webhookChannel.Writer.TryWrite(new PurgeNotification(purgeAction, pattern));
        }

        private async Task ProcessWebhookBroadcastsAsync()
        {
            try
            {
                while (await _webhookChannel.Reader.WaitToReadAsync(_cts.Token).ConfigureAwait(false))
                {
                    while (_webhookChannel.Reader.TryRead(out var notification))
                    {
                        foreach (var endpoint in _webhookEndpoints)
                        {
                            await DeliverWebhookWithRetryAsync(endpoint, notification).ConfigureAwait(false);
                        }
                    }
                }
            }
            catch (OperationCanceledException) { }
        }

        private async Task DeliverWebhookWithRetryAsync(string endpoint, PurgeNotification notification)
        {
            const int MaxRetries = 4;
            var payload = $"{{\"action\":\"{notification.Action}\",\"pattern\":\"{notification.Pattern}\"}}";
            var content = new StringContent(payload, Encoding.UTF8, "application/json");

            for (int attempt = 1; attempt <= MaxRetries; attempt++)
            {
                try
                {
                    using var response = await _httpClient.PostAsync(endpoint, content, _cts.Token).ConfigureAwait(false);
                    if (response.IsSuccessStatusCode)
                    {
                        Console.WriteLine($"[Webhook Broadcast Success] Destination: {endpoint} -> Action: {notification.Action}");
                        return;
                    }
                }
                catch
                {
                    // Catch network/timeout errors, trigger retry loop
                }

                // Resilient Jittered Exponential Backoff Execution: 200ms, 400ms, 800ms, 1600ms + random offset
                var delay = TimeSpan.FromMilliseconds(Math.Pow(2, attempt) * 100 + Random.Shared.Next(10, 80));
                Console.WriteLine($"[Webhook Retrying] Endpoint {endpoint} failed. Re-attempt {attempt}/{MaxRetries} in {delay.TotalMilliseconds}ms.");
                await Task.Delay(delay, _cts.Token).ConfigureAwait(false);
            }

            Console.ForegroundColor = ConsoleColor.DarkRed;
            Console.WriteLine($"[Webhook Poison-Queue] Failed to deliver invalidation payload to {endpoint} after {MaxRetries} attempts.");
            Console.ResetColor();
        }

        public async ValueTask DisposeAsync()
        {
            _cts.Cancel();
            try
            {
                await _webhookBroadcasterTask.ConfigureAwait(false);
            }
            catch { }
            _httpClient.Dispose();
            _cts.Dispose();
            GC.SuppressFinalize(this);
        }
    }

    #endregion

    #region Edge Proxy Ingester (Request Normalization, Pattern Matching & Collapsing)

    public class EdgeProxyIngester : IAsyncDisposable
    {
        private readonly ICacheTierManager _cacheTierManager;
        private readonly IPurgeController _purgeController;
        private readonly HttpListener _listener = new();
        private readonly ConcurrentDictionary<string, Lazy<Task<CacheItem>>> _originRequests = new();
        private readonly CancellationTokenSource _cts = new();
        private Task? _listenerTask;

        public EdgeProxyIngester(ICacheTierManager cacheTierManager, IPurgeController purgeController, int listeningPort)
        {
            _cacheTierManager = cacheTierManager;
            _purgeController = purgeController;
            _listener.Prefixes.Add($"http://127.0.0.1:{listeningPort}/");
        }

        public void Start()
        {
            _listener.Start();
            _listenerTask = Task.Run(ListenLoopAsync);
            Console.WriteLine($"[Gateway Ingester] Enterprise CDN active and parsing on http://127.0.0.1:8080/");
        }

        private async Task ListenLoopAsync()
        {
            while (!_cts.IsCancellationRequested && _listener.IsListening)
            {
                try
                {
                    var context = await _listener.GetContextAsync().ConfigureAwait(false);
                    _ = Task.Run(() => ProcessHttpRequestAsync(context)); // Handle request concurrently
                }
                catch (HttpListenerException) when (_cts.IsCancellationRequested)
                {
                    break;
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"[Internal Proxy Crash] Http Gateway error: {ex.Message}");
                }
            }
        }

        private async Task ProcessHttpRequestAsync(HttpListenerContext context)
        {
            using var response = context.Response;
            var request = context.Request;
            var path = request.Url?.AbsolutePath ?? "/";

            // Support Purge requests via the Gateway Admin API
            if (path.StartsWith("/admin/purge", StringComparison.OrdinalIgnoreCase))
            {
                await HandleAdminPurgeAsync(context, response).ConfigureAwait(false);
                return;
            }

            // Standard CDN Delivery Workflow
            var cacheKey = NormalizeCacheKey(request);
            var (mediaType, defaultTtl) = ClassifyMediaPattern(path);

            var cachedItem = await _cacheTierManager.GetAsync(cacheKey).ConfigureAwait(false);
            if (cachedItem != null)
            {
                Console.ForegroundColor = ConsoleColor.Green;
                Console.WriteLine($"[Cache HIT] Key: '{cacheKey}' | Type: {mediaType}");
                Console.ResetColor();

                response.Headers["X-Cache"] = "HIT";
                response.Headers["X-Cache-Key"] = cacheKey;
                response.ContentType = cachedItem.ContentType;
                response.ContentLength64 = cachedItem.Data.Length;
                await response.OutputStream.WriteAsync(cachedItem.Data).ConfigureAwait(false);
                return;
            }

            Console.ForegroundColor = ConsoleColor.Yellow;
            Console.WriteLine($"[Cache MISS] Key: '{cacheKey}' | Deploying Origin Shield Protection...");
            Console.ResetColor();

            // Origin Request Collapsing / Stampede Prevention using Lazy Task Collapsing
            try
            {
                var collapsedTask = _originRequests.GetOrAdd(cacheKey, key => 
                    new Lazy<Task<CacheItem>>(() => FetchFromOriginAsync(key, path, request.Headers["X-Origin-Host"] ?? "http://origin-upstream.internal", defaultTtl))
                );

                var resolvedPayload = await collapsedTask.Value.ConfigureAwait(false);

                // Save to Multi-Tier Engine
                await _cacheTierManager.SetAsync(resolvedPayload).ConfigureAwait(false);
                await _purgeController.RegisterKeyAsync(resolvedPayload.Key, resolvedPayload.Tags).ConfigureAwait(false);

                response.Headers["X-Cache"] = "MISS";
                response.Headers["X-Cache-Key"] = cacheKey;
                response.ContentType = resolvedPayload.ContentType;
                response.ContentLength64 = resolvedPayload.Data.Length;
                await response.OutputStream.WriteAsync(resolvedPayload.Data).ConfigureAwait(false);
            }
            catch (Exception ex)
            {
                response.StatusCode = (int)HttpStatusCode.InternalServerError;
                var errorMsg = Encoding.UTF8.GetBytes($"Origin Gateway Connection Error: {ex.Message}");
