        #region Internal Edge Request Parsers & Normalization

        public string NormalizeCacheKey(HttpListenerRequest request)
        {
            var url = request.Url ?? new Uri("http://localhost/");
            var path = url.AbsolutePath.ToLowerInvariant();

            // Clean up and sort query string arguments to avoid cache fragmentation on randomized query string ordering
            var parsedQuery = System.Web.HttpUtility.ParseQueryString(url.Query);
            var sortedParams = parsedQuery.AllKeys
                .Where(k => k != null && !k.StartsWith("utm_", StringComparison.OrdinalIgnoreCase)) // Strip tracking analytics tokens
                .OrderBy(k => k)
                .Select(k => $"{Uri.EscapeDataString(k!)?.ToLowerInvariant()}={Uri.EscapeDataString(parsedQuery[k] ?? string.Empty)?.ToLowerInvariant()}");

            var normalizedQuery = string.Join("&", sortedParams);

            // Handle device classification headers if matching adaptive content variants (e.g. mobile vs desktop layouts)
            var deviceType = request.Headers["X-Device-Type"]?.ToLowerInvariant() ?? "desktop";

            // Content Encoding support (Gzip vs Brotli tracking)
            var acceptEncoding = request.Headers["Accept-Encoding"]?.ToLowerInvariant() ?? "";
            string encodingSegment = "raw";
            if (acceptEncoding.Contains("br")) encodingSegment = "br";
            else if (acceptEncoding.Contains("gzip")) encodingSegment = "gzip";

            var builtKey = $"{deviceType}:{encodingSegment}:{path}";
            if (!string.IsNullOrEmpty(normalizedQuery))
            {
                builtKey += "?" + normalizedQuery;
            }

            return builtKey;
        }

        public (MediaType Type, TimeSpan DefaultTtl) ClassifyMediaPattern(string path)
        {
            var extension = Path.GetExtension(path).ToLowerInvariant();

            return extension switch
            {
                ".m3u8" => (MediaType.HlsPlaylist, TimeSpan.FromSeconds(2)), // Playlists change live; short dynamic TTL
                ".ts" => (MediaType.HlsSegment, TimeSpan.FromDays(305)),     // Segments are immutable; extreme caching
                ".mpd" => (MediaType.DashManifest, TimeSpan.FromSeconds(2)),
                ".m4s" => (MediaType.DashSegment, TimeSpan.FromDays(305)),
                ".mp4" or ".webm" or ".mkv" => (MediaType.ProgressiveMedia, TimeSpan.FromHours(24)),
                _ => (MediaType.Generic, TimeSpan.FromMinutes(10))
            };
        }

        private async Task<CacheItem> FetchFromOriginAsync(string cacheKey, string absolutePath, string originHost, TimeSpan ttl)
        {
            // Simulating physical network Round Trip Time (RTT) delay to origin servers
            await Task.Delay(Random.Shared.Next(40, 110)).ConfigureAwait(false);

            // Generate mock payload content representation matching real CDN deployment
            var dummyPayloadSize = absolutePath.EndsWith(".ts") || absolutePath.EndsWith(".m4s") ? 1024 * 768 : 1024 * 5; // Simulating large media payload chunk
            var binaryBuffer = new byte[dummyPayloadSize];
            Random.Shared.NextBytes(binaryBuffer);

            // Custom Enterprise Media Tags categorization
            var tags = new List<string> { "media", "origin-shield" };
            if (absolutePath.Contains("/hls/")) tags.Add("hls");
            if (absolutePath.Contains("/dash/")) tags.Add("dash");
            if (absolutePath.Contains("/manifest")) tags.Add("manifest");

            var contentType = absolutePath.EndsWith(".m3u8") ? "application/x-mpegURL" 
                            : absolutePath.EndsWith(".ts") ? "video/MP2T" 
                            : "application/octet-stream";

            return new CacheItem(
                Key: cacheKey,
                Data: binaryBuffer,
                ContentType: contentType,
                Tags: tags.ToArray(),
                ExpiresAt: DateTime.UtcNow.Add(ttl)
            );
        }

